values ('M72605', 7, 'HSK 7–9 · HSK 3.0 загвар шалгалт №5 (全真模拟)', 91, 180, true, '[{"skill": "listening", "audio_url": "/mock-tests/m72605/listening.mp3", "time_min": 30, "parts": [{"part": 1, "range": [1, 10], "q_type": "judge", "desc": "Үнэн/худал (√/×)"}, {"part": 2, "range": [11, 22], "q_type": "choice", "desc": "Сонгох ба нөхөх (ярилцлага)"}, {"part": 3, "range": [23, 40], "q_type": "choice", "desc": "Сонгох ба нөхөх (лекц, илтгэл)"}]}, {"skill": "reading", "audio_url": null, "time_min": 60, "parts": [{"part": 1, "range": [41, 68], "q_type": "choice", "desc": "Эхийг уншиж зөв хариулт сонгох"}, {"part": 2, "range": [69, 73], "q_type": "choice", "desc": "Догол мөрийн дараалал"}, {"part": 3, "range": [74, 87], "q_type": "essay", "desc": "Асуултад товч хариулах"}]}, {"skill": "writing", "audio_url": null, "time_min": 90, "parts": [{"part": 1, "range": [88, 88], "q_type": "essay_picture", "desc": "Графикийн тайлбар"}, {"part": 2, "range": [89, 89], "q_type": "essay", "desc": "Сэдэвт эсээ"}, {"part": 3, "range": [90, 91], "q_type": "essay", "desc": "Орчуулга (бичгийн)"}]}]'::jsonb, true)
