insert into public.mock_test_questions (test_id, skill, part, q_no, q_type, stem, options, correct_answer, autograde, points, audio_url, image_url, needs_image, tags, explanation_mn, audio_start_sec, audio_end_sec, audio_transcript, tutor_note) values
('M72605','listening',1,1,'judge','水豚是啮齿类动物。',null,'√','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эхний өгүүлбэр капибарааг мэрэгч амьтдын ертөнцийн «аварга» гэж нэрлэсэн тул мэрэгч амьтан мөн.',86.63,274.66,'在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？
首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。
而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。
最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。','{"transcript": [{"zh": "在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？", "mn": "Дэлхийн биологийн олон янз байдлын эрдэнийн санд мэрэгч амьтдын ертөнцийн нэгэн зөөлөн «аварга» нуугдаж байна. Энэ нь капибара юм. Тэгвэл капибарааг ингэтлээ хайрлуулдаг юм нь юу вэ?"}, {"zh": "首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。", "mn": "Юуны өмнө тэдний эсэргүүцэх аргагүй хөөрхөн төрхийг дурдах хэрэгтэй. Бөөрөнхий биеэс нь ч, сониуч цайлхан нүднээс нь ч дөхөж очоод аятайхан энхрийлмээр санагддаг. Энэ төрөлхийн дотно занг нь ачаар капибара богино хугацаанд гэрийн тэжээвэр амьтдын шинэ дуртай нь болж, олон гэрэл зурагчин, амьтан хамгаалагчийн анхаарлыг татлаа."}, {"zh": "而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。", "mn": "Гадаад төрхөөс гадна зан чанар нь хайрлагдах чухал шалтгаан юм. Тэд зөөлөн, найрсаг, дайрах занг бараг үгүй, хүн болон бусад амьтантай эв найртай зэрэгцэн амьдардаг. Энэ найрсаг зан тэднийг сүргийнхээ дунд ч, хүмүүсийн ертөнцөд ч олон найзтай болгосон. Хүмүүс тэдэнтэй харьцахдаа урьд өмнө мэдэрч байгаагүй тайван, таатай байдлыг мэдэрч, бүх зовнил нь тэдний тэнэг хөөрхөн байдлаар арилчихсан юм шиг санагддаг."}, {"zh": "最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。", "mn": "Эцэст нь, нийгмийн сүлжээ, интернет дэлгэрэх тусам капибарагийн хөөрхөн байдал, хөгийн түүхүүд өргөн тархаж, нэр хүнд нь өсөн «од», «интернэт од» болжээ. Энэ эерэг олон нийтийн уур амьсгал, өргөн тархалт нь капибарагийн алдар хүндэд бүдүүлэг нөлөө үзүүлсэн нь тодорхой."}], "key": "啮齿动物界的“巨人”——水豚", "keyMn": "мэрэгч амьтдын «аварга» капибара", "why": "Эхний өгүүлбэр капибарааг мэрэгч амьтдын ертөнцийн «аварга» гэж нэрлэсэн тул мэрэгч амьтан мөн.", "words": [{"zh": "啮齿动物", "pinyin": "nièchǐ dòngwù", "mn": "мэрэгч амьтан"}, {"zh": "水豚", "pinyin": "shuǐtún", "mn": "капибара"}, {"zh": "宠物", "pinyin": "chǒngwù", "mn": "тэжээвэр амьтан"}]}'::jsonb),
('M72605','listening',1,2,'judge','水豚的可爱外表让它们拥有天然的亲和力。',null,'√','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Хоёр дахь догол мөрөнд «хөөрхөн төрх нь төрөлхийн дотно занг өгдөг» гэсэн тул зөв.',86.63,274.66,'在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？
首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。
而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。
最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。','{"transcript": [{"zh": "在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？", "mn": "Дэлхийн биологийн олон янз байдлын эрдэнийн санд мэрэгч амьтдын ертөнцийн нэгэн зөөлөн «аварга» нуугдаж байна. Энэ нь капибара юм. Тэгвэл капибарааг ингэтлээ хайрлуулдаг юм нь юу вэ?"}, {"zh": "首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。", "mn": "Юуны өмнө тэдний эсэргүүцэх аргагүй хөөрхөн төрхийг дурдах хэрэгтэй. Бөөрөнхий биеэс нь ч, сониуч цайлхан нүднээс нь ч дөхөж очоод аятайхан энхрийлмээр санагддаг. Энэ төрөлхийн дотно занг нь ачаар капибара богино хугацаанд гэрийн тэжээвэр амьтдын шинэ дуртай нь болж, олон гэрэл зурагчин, амьтан хамгаалагчийн анхаарлыг татлаа."}, {"zh": "而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。", "mn": "Гадаад төрхөөс гадна зан чанар нь хайрлагдах чухал шалтгаан юм. Тэд зөөлөн, найрсаг, дайрах занг бараг үгүй, хүн болон бусад амьтантай эв найртай зэрэгцэн амьдардаг. Энэ найрсаг зан тэднийг сүргийнхээ дунд ч, хүмүүсийн ертөнцөд ч олон найзтай болгосон. Хүмүүс тэдэнтэй харьцахдаа урьд өмнө мэдэрч байгаагүй тайван, таатай байдлыг мэдэрч, бүх зовнил нь тэдний тэнэг хөөрхөн байдлаар арилчихсан юм шиг санагддаг."}, {"zh": "最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。", "mn": "Эцэст нь, нийгмийн сүлжээ, интернет дэлгэрэх тусам капибарагийн хөөрхөн байдал, хөгийн түүхүүд өргөн тархаж, нэр хүнд нь өсөн «од», «интернэт од» болжээ. Энэ эерэг олон нийтийн уур амьсгал, өргөн тархалт нь капибарагийн алдар хүндэд бүдүүлэг нөлөө үзүүлсэн нь тодорхой."}], "key": "这种天然的亲和力", "keyMn": "энэ төрөлхийн дотно занг", "why": "Хоёр дахь догол мөрөнд «хөөрхөн төрх нь төрөлхийн дотно занг өгдөг» гэсэн тул зөв.", "words": [{"zh": "外表", "pinyin": "wàibiǎo", "mn": "гадаад төрх"}, {"zh": "亲和力", "pinyin": "qīnhélì", "mn": "дотно занг"}, {"zh": "可爱", "pinyin": "kě''ài", "mn": "хөөрхөн"}]}'::jsonb),
('M72605','listening',1,3,'judge','水豚完全没有攻击性，和任何动物都能和谐共处。',null,'×','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эх «几乎没有攻击性» (бараг дайрах занг үгүй) гэсэн. Асуултад «完全没有» (огт үгүй), «任何动物» (ямар ч амьтан) гэж хэтрүүлсэн тул буруу.',86.63,274.66,'在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？
首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。
而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。
最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。','{"transcript": [{"zh": "在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？", "mn": "Дэлхийн биологийн олон янз байдлын эрдэнийн санд мэрэгч амьтдын ертөнцийн нэгэн зөөлөн «аварга» нуугдаж байна. Энэ нь капибара юм. Тэгвэл капибарааг ингэтлээ хайрлуулдаг юм нь юу вэ?"}, {"zh": "首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。", "mn": "Юуны өмнө тэдний эсэргүүцэх аргагүй хөөрхөн төрхийг дурдах хэрэгтэй. Бөөрөнхий биеэс нь ч, сониуч цайлхан нүднээс нь ч дөхөж очоод аятайхан энхрийлмээр санагддаг. Энэ төрөлхийн дотно занг нь ачаар капибара богино хугацаанд гэрийн тэжээвэр амьтдын шинэ дуртай нь болж, олон гэрэл зурагчин, амьтан хамгаалагчийн анхаарлыг татлаа."}, {"zh": "而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。", "mn": "Гадаад төрхөөс гадна зан чанар нь хайрлагдах чухал шалтгаан юм. Тэд зөөлөн, найрсаг, дайрах занг бараг үгүй, хүн болон бусад амьтантай эв найртай зэрэгцэн амьдардаг. Энэ найрсаг зан тэднийг сүргийнхээ дунд ч, хүмүүсийн ертөнцөд ч олон найзтай болгосон. Хүмүүс тэдэнтэй харьцахдаа урьд өмнө мэдэрч байгаагүй тайван, таатай байдлыг мэдэрч, бүх зовнил нь тэдний тэнэг хөөрхөн байдлаар арилчихсан юм шиг санагддаг."}, {"zh": "最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。", "mn": "Эцэст нь, нийгмийн сүлжээ, интернет дэлгэрэх тусам капибарагийн хөөрхөн байдал, хөгийн түүхүүд өргөн тархаж, нэр хүнд нь өсөн «од», «интернэт од» болжээ. Энэ эерэг олон нийтийн уур амьсгал, өргөн тархалт нь капибарагийн алдар хүндэд бүдүүлэг нөлөө үзүүлсэн нь тодорхой."}], "key": "几乎没有攻击性", "keyMn": "дайрах занг бараг үгүй", "why": "Эх «几乎没有攻击性» (бараг дайрах занг үгүй) гэсэн. Асуултад «完全没有» (огт үгүй), «任何动物» (ямар ч амьтан) гэж хэтрүүлсэн тул буруу.", "trap": "«几乎» (бараг) ба «完全» (бүрэн) гэсэн үгийн ялгаа.", "tip": "Туйлын үг (完全, 所有, 任何) орсон дүгнэлтэд сэжиглэж сонс.", "words": [{"zh": "几乎", "pinyin": "jīhū", "mn": "бараг"}, {"zh": "攻击性", "pinyin": "gōngjīxìng", "mn": "дайрах занг"}, {"zh": "和谐共处", "pinyin": "héxié gòngchǔ", "mn": "эв найртай зэрэгцэн оршин тогтнох"}]}'::jsonb),
('M72605','listening',1,4,'judge','人们在和水豚互动的过程中，仿佛所有的烦恼都会消失。',null,'√','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Гурав дахь догол мөрийн төгсгөл: «仿佛所有的烦恼都被它们的憨态可掬化解掉了» — санаа зовнил арилчихсан юм шиг санагддаг.',86.63,274.66,'在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？
首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。
而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。
最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。','{"transcript": [{"zh": "在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？", "mn": "Дэлхийн биологийн олон янз байдлын эрдэнийн санд мэрэгч амьтдын ертөнцийн нэгэн зөөлөн «аварга» нуугдаж байна. Энэ нь капибара юм. Тэгвэл капибарааг ингэтлээ хайрлуулдаг юм нь юу вэ?"}, {"zh": "首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。", "mn": "Юуны өмнө тэдний эсэргүүцэх аргагүй хөөрхөн төрхийг дурдах хэрэгтэй. Бөөрөнхий биеэс нь ч, сониуч цайлхан нүднээс нь ч дөхөж очоод аятайхан энхрийлмээр санагддаг. Энэ төрөлхийн дотно занг нь ачаар капибара богино хугацаанд гэрийн тэжээвэр амьтдын шинэ дуртай нь болж, олон гэрэл зурагчин, амьтан хамгаалагчийн анхаарлыг татлаа."}, {"zh": "而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。", "mn": "Гадаад төрхөөс гадна зан чанар нь хайрлагдах чухал шалтгаан юм. Тэд зөөлөн, найрсаг, дайрах занг бараг үгүй, хүн болон бусад амьтантай эв найртай зэрэгцэн амьдардаг. Энэ найрсаг зан тэднийг сүргийнхээ дунд ч, хүмүүсийн ертөнцөд ч олон найзтай болгосон. Хүмүүс тэдэнтэй харьцахдаа урьд өмнө мэдэрч байгаагүй тайван, таатай байдлыг мэдэрч, бүх зовнил нь тэдний тэнэг хөөрхөн байдлаар арилчихсан юм шиг санагддаг."}, {"zh": "最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。", "mn": "Эцэст нь, нийгмийн сүлжээ, интернет дэлгэрэх тусам капибарагийн хөөрхөн байдал, хөгийн түүхүүд өргөн тархаж, нэр хүнд нь өсөн «од», «интернэт од» болжээ. Энэ эерэг олон нийтийн уур амьсгал, өргөн тархалт нь капибарагийн алдар хүндэд бүдүүлэг нөлөө үзүүлсэн нь тодорхой."}], "key": "仿佛所有的烦恼都被……化解掉了", "keyMn": "бүх зовнил арилчихсан юм шиг", "why": "Гурав дахь догол мөрийн төгсгөл: «仿佛所有的烦恼都被它们的憨态可掬化解掉了» — санаа зовнил арилчихсан юм шиг санагддаг.", "words": [{"zh": "烦恼", "pinyin": "fánnǎo", "mn": "санаа зовнил"}, {"zh": "化解", "pinyin": "huàjiě", "mn": "арилгах, тайвшруулах"}, {"zh": "放松", "pinyin": "fàngsōng", "mn": "тайвшрах"}]}'::jsonb),
('M72605','listening',1,5,'judge','这则新闻主要谈的是水豚让人们感到放松的原因。',null,'×','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Мэдээний гол сэдэв бол капибарааг яагаад олон хүн хайрладаг вэ (төрх, зан, нийгмийн сүлжээ). Тайвшруулдаг нь зөвхөн нэг жижиг дэлгэрэнгүй.',86.63,274.66,'在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？
首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。
而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。
最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。','{"transcript": [{"zh": "在地球的生物多样性宝库中，隐藏着一个温柔的啮齿动物界的“巨人”——水豚。那么，究竟是什么让水豚如此受欢迎呢？", "mn": "Дэлхийн биологийн олон янз байдлын эрдэнийн санд мэрэгч амьтдын ертөнцийн нэгэн зөөлөн «аварга» нуугдаж байна. Энэ нь капибара юм. Тэгвэл капибарааг ингэтлээ хайрлуулдаг юм нь юу вэ?"}, {"zh": "首先不得不提的是它们那令人难以抗拒的可爱外表。无论是那圆滚滚的身体，还是那双充满好奇与纯真的眼睛，都让人忍不住想要靠近，给予它们最温柔的呵护。这种天然的亲和力，让水豚迅速成为宠物界的新宠儿，也吸引了无数摄影爱好者和动物保护者的目光。", "mn": "Юуны өмнө тэдний эсэргүүцэх аргагүй хөөрхөн төрхийг дурдах хэрэгтэй. Бөөрөнхий биеэс нь ч, сониуч цайлхан нүднээс нь ч дөхөж очоод аятайхан энхрийлмээр санагддаг. Энэ төрөлхийн дотно занг нь ачаар капибара богино хугацаанд гэрийн тэжээвэр амьтдын шинэ дуртай нь болж, олон гэрэл зурагчин, амьтан хамгаалагчийн анхаарлыг татлаа."}, {"zh": "而除了外表之外，水豚的性格更是它们受欢迎的重要原因之一。它们温和友善，几乎没有攻击性，与人类和其他动物都能和谐共处。这种友善的性格不仅让水豚在家族群体中备受喜爱，也为它们在人类世界中赢得了众多朋友。人们在与水豚的互动中感受到了前所未有的放松与愉悦，仿佛所有的烦恼都被它们的憨态可掬化解掉了。", "mn": "Гадаад төрхөөс гадна зан чанар нь хайрлагдах чухал шалтгаан юм. Тэд зөөлөн, найрсаг, дайрах занг бараг үгүй, хүн болон бусад амьтантай эв найртай зэрэгцэн амьдардаг. Энэ найрсаг зан тэднийг сүргийнхээ дунд ч, хүмүүсийн ертөнцөд ч олон найзтай болгосон. Хүмүүс тэдэнтэй харьцахдаа урьд өмнө мэдэрч байгаагүй тайван, таатай байдлыг мэдэрч, бүх зовнил нь тэдний тэнэг хөөрхөн байдлаар арилчихсан юм шиг санагддаг."}, {"zh": "最后，随着社交媒体和网络的普及，水豚的萌态和趣事被广泛传播，进一步提升了它们的知名度，它们也成了网络上的“明星”和“网红”。这种正面的舆论氛围和广泛的传播效应，无疑为水豚的受欢迎程度增添了助力。", "mn": "Эцэст нь, нийгмийн сүлжээ, интернет дэлгэрэх тусам капибарагийн хөөрхөн байдал, хөгийн түүхүүд өргөн тархаж, нэр хүнд нь өсөн «од», «интернэт од» болжээ. Энэ эерэг олон нийтийн уур амьсгал, өргөн тархалт нь капибарагийн алдар хүндэд бүдүүлэг нөлөө үзүүлсэн нь тодорхой."}], "key": "究竟是什么让水豚如此受欢迎呢？", "keyMn": "капибарааг яагаад ингэтлээ хайрладаг вэ?", "why": "Мэдээний гол сэдэв бол капибарааг яагаад олон хүн хайрладаг вэ (төрх, зан, нийгмийн сүлжээ). Тайвшруулдаг нь зөвхөн нэг жижиг дэлгэрэнгүй.", "trap": "Задгай жижиг мэдээллийг «гол сэдэв» болгож андуурах.", "tip": "Эхний асуултай өгүүлбэр ихэвчлэн гол сэдвийг хэлдэг.", "words": [{"zh": "受欢迎", "pinyin": "shòu huānyíng", "mn": "алдартай, хайртай"}, {"zh": "主要", "pinyin": "zhǔyào", "mn": "гол"}, {"zh": "原因", "pinyin": "yuányīn", "mn": "шалтгаан"}]}'::jsonb),
('M72605','listening',1,6,'judge','滑雪是一项受到年轻人欢迎的冬季运动。',null,'√','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эх «滑雪…成为冬季“顶流”运动», «人设几乎很难让年轻人拒绝» — залуучуудад алдартай өвлийн спорт.',274.96,446.97,'滑雪之所以成为冬季“顶流”运动，其自身魅力不可小瞧。
时尚、高级、酷……滑雪的人设几乎很难让年轻人拒绝。无论男女，都对这项运动着迷。雪场上滑雪服和雪板五彩斑斓，不失为一道亮丽风景。很多人学会滑雪后都会发现：根本停不下来！
有研究发现，滑雪过程中大脑会分泌一种神经化学物质——多巴胺，让人产生愉悦感。人体有一种奖励机制，滑雪可以带来愉悦体验并一次次反馈给大脑，大脑就会下达再次体验的命令。这就是滑雪让人“上瘾”的原因。
除了多巴胺外，滑雪时大脑还会分泌一种调节情绪的激素——内啡肽，它能调节神经和大脑系统，让人感到放松、愉快。
此外，滑雪对身体也有很多好处，比如改善心血管健康和睡眠，增强力量、敏捷性和协调性，等等。高速下落滑行时，人处于低氧状态，可以使肺和心脏更加努力地工作。而且，滑雪主要靠腰腹和腿部发力，经常滑雪可以增强下肢肌肉力量、平衡能力和核心力量。
在一些情况下，滑雪的速度可以很快。熟练的滑手从山顶滑行下来，速度可达数十公里每小时，这个过程会促进肾上腺素分泌，产生失重感和快感。','{"transcript": [{"zh": "滑雪之所以成为冬季“顶流”运动，其自身魅力不可小瞧。", "mn": "Цанаар гулгах нь өвлийн «топ» спорт болсон нь өөрийн дур булаам байдлаас шалтгаалж байгаа бөгөөд үүнийг дутуу үзэж болохгүй."}, {"zh": "时尚、高级、酷……滑雪的人设几乎很难让年轻人拒绝。无论男女，都对这项运动着迷。雪场上滑雪服和雪板五彩斑斓，不失为一道亮丽风景。很多人学会滑雪后都会发现：根本停不下来！", "mn": "Загварлаг, өндөр зэрэглэлийн, мундаг... цанаар гулгагчийн дүр төрх залуучуудыг татахгүй байхад хэцүү. Эрэгтэй, эмэгтэй хэн ч энэ спортод дуртай. Цанын талбай дээр цанын хувцас, цана нь олон өнгөөр гялалзаж, үзэсгэлэнтэй өнгө аяс бүрдүүлдэг. Олон хүн цана сурсныхаа дараа «зогсоож огт болохгүй байна!» гэдгийг мэдэрдэг."}, {"zh": "有研究发现，滑雪过程中大脑会分泌一种神经化学物质——多巴胺，让人产生愉悦感。人体有一种奖励机制，滑雪可以带来愉悦体验并一次次反馈给大脑，大脑就会下达再次体验的命令。这就是滑雪让人“上瘾”的原因。", "mn": "Судалгаагаар цанаар гулгах үед тархи допамин хэмээх мэдрэлийн химийн бодис ялгаруулж, хүнд таашаал төрүүлдэг нь тогтоогджээ. Хүний биед шагналын механизм бий. Цана таатай мэдрэмж өгч, түүнийгээ дахин дахин тархинд буцаахад тархи дахин туршихыг тушаадаг. Цана хүнийг «донтуулдаг» шалтгаан энэ юм."}, {"zh": "除了多巴胺外，滑雪时大脑还会分泌一种调节情绪的激素——内啡肽，它能调节神经和大脑系统，让人感到放松、愉快。", "mn": "Допамины дээр цанаар гулгахад тархи сэтгэл хөдлөлийг зохицуулдаг дааврын бодис эндорфиныг бас ялгаруулдаг. Энэ нь мэдрэл ба тархины системийг зохицуулж, хүнийг тайван, таатай болгодог."}, {"zh": "此外，滑雪对身体也有很多好处，比如改善心血管健康和睡眠，增强力量、敏捷性和协调性，等等。高速下落滑行时，人处于低氧状态，可以使肺和心脏更加努力地工作。而且，滑雪主要靠腰腹和腿部发力，经常滑雪可以增强下肢肌肉力量、平衡能力和核心力量。", "mn": "Үүнээс гадна цана биед олон ашигтай. Жишээ нь зүрх судасны эрүүл мэнд, нойрыг сайжруулж, хүч, самбаа, зохицлыг нэмэгдүүлнэ. Өндрөөс хурдтай уруудахад хүн хүчилтөрөгч дутмаг төлөвт орж, уушиг, зүрх илүү хичээнгүйлэн ажиллана. Мөн цанаар гулгахад голдуу бэлхүүс, хэвлий, хөлөөр хүч гаргадаг тул байнга гулгавал хөлийн булчингийн хүч, тэнцвэр, голын хүчийг сайжруулна."}, {"zh": "在一些情况下，滑雪的速度可以很快。熟练的滑手从山顶滑行下来，速度可达数十公里每小时，这个过程会促进肾上腺素分泌，产生失重感和快感。", "mn": "Зарим тохиолдолд цанын хурд маш өндөр байж болно. Чадварлаг гулгагч уулын оройгоос гулгаж буухад хурд нь цагт хэдэн арван километрт хүрч, энэ үед адреналин ялгарч, жингүй мэт мэдрэмж, таашаал төрдөг."}], "key": "滑雪的人设几乎很难让年轻人拒绝", "keyMn": "цанаар гулгагчийн дүр төрх залуучуудад татагдахгүй байхад хэцүү", "why": "Эх «滑雪…成为冬季“顶流”运动», «人设几乎很难让年轻人拒绝» — залуучуудад алдартай өвлийн спорт.", "words": [{"zh": "顶流", "pinyin": "dǐngliú", "mn": "топ, хамгийн алдартай"}, {"zh": "年轻人", "pinyin": "niánqīngrén", "mn": "залуучууд"}, {"zh": "冬季", "pinyin": "dōngjì", "mn": "өвөл"}]}'::jsonb),
('M72605','listening',1,7,'judge','滑雪服和雪板的颜色通常比较单调。',null,'×','auto',1,'/mock-tests/m72605/listening.mp3',null,false,array['sk.listening.judge','voc.hsk6','hsk30']::text[],'Эхэд «滑雪服和雪板五彩斑斓» (олон өнгөөр гялалзана) гэсэн тул «单调» (нэг хэвийн) гэдэг нь буруу.',274.96,446.97,'滑雪之所以成为冬季“顶流”运动，其自身魅力不可小瞧。
时尚、高级、酷……滑雪的人设几乎很难让年轻人拒绝。无论男女，都对这项运动着迷。雪场上滑雪服和雪板五彩斑斓，不失为一道亮丽风景。很多人学会滑雪后都会发现：根本停不下来！
有研究发现，滑雪过程中大脑会分泌一种神经化学物质——多巴胺，让人产生愉悦感。人体有一种奖励机制，滑雪可以带来愉悦体验并一次次反馈给大脑，大脑就会下达再次体验的命令。这就是滑雪让人“上瘾”的原因。
